"""Evidence-based clinical condition rules engine and conflict resolution hierarchy."""

from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, List

import yaml

from nutri.logging import setup_logger

logger = setup_logger(__name__)

RULES_CONFIG_PATH = Path(__file__).resolve().parent / "clinical_rules.yaml"


@dataclass
class ClinicalConstraint:
    """Represents a specific nutrient constraint generated by a clinical guideline."""

    nutrient: str
    bound_type: str  # 'max' or 'min'
    value: float
    unit: str
    condition_key: str
    condition_name: str
    citation: str
    reason: str


# In-memory registry for dynamic custom clinical rule extension
_CUSTOM_RULES_REGISTRY: Dict[str, Any] = {}


def load_clinical_rules_config() -> Dict[str, Any]:
    """Load clinical rules from YAML config merged with custom registry."""
    if not RULES_CONFIG_PATH.exists():
        raise FileNotFoundError(f"Clinical rules YAML not found at {RULES_CONFIG_PATH}")
    with open(RULES_CONFIG_PATH, "r", encoding="utf-8") as f:
        config = yaml.safe_load(f) or {}

    # Merge custom rules
    if _CUSTOM_RULES_REGISTRY:
        if "conditions" not in config:
            config["conditions"] = {}
        config["conditions"].update(_CUSTOM_RULES_REGISTRY)

    return config


def register_custom_condition_rule(condition_key: str, rule_dict: Dict[str, Any]) -> None:
    """Extension point: register a new clinical condition rule dynamically at runtime."""
    _CUSTOM_RULES_REGISTRY[condition_key.lower().strip()] = rule_dict
    logger.info("Registered custom clinical condition: %s", condition_key)


def normalize_condition_name(raw_name: str) -> str:
    """Normalize raw dataset Disease_Type or user input to canonical key."""
    clean = str(raw_name).lower().strip().replace(" ", "_").replace("-", "_")
    mapping = {
        "diabetes": "diabetes",
        "type_2_diabetes": "diabetes",
        "hypertension": "hypertension",
        "high_blood_pressure": "hypertension",
        "high_cholesterol": "high_cholesterol",
        "hypercholesterolemia": "high_cholesterol",
        "dyslipidemia": "high_cholesterol",
        "obesity": "obesity",
        "overweight": "obesity",
    }
    return mapping.get(clean, clean)


def resolve_clinical_rules(
    active_conditions: List[str],
    active_restrictions: List[str],
    base_targets: Dict[str, Any],
    weight_kg: float,
) -> Dict[str, Any]:
    """Combine multiple clinical guidelines and resolve nutrient conflicts strictly.

    Hierarchy & Safety Principle:
    - Upper bounds (max limits, e.g. sodium, sugar, saturated fat):
      The STRICTEST (lowest numerical value) bound is enforced.
    - Lower bounds (min targets, e.g. fiber, protein):
      The STRICTEST (highest numerical value) target is enforced.
    - Audit Trail:
      Every modified constraint explicitly cites which condition ruled and why.

    Args:
        active_conditions: List of medical conditions (e.g. ['Hypertension', 'Diabetes']).
        active_restrictions: Dietary restriction tags (e.g. ['low_sodium', 'vegetarian']).
        base_targets: Baseline target calculations from assess engine.
        weight_kg: Patient body weight in kilograms.

    Returns:
        Dict with adjusted targets, 'why this limit' audit trail, and clinical advice.
    """
    config = load_clinical_rules_config()
    conditions_cfg = config.get("conditions", {})

    target_kcal = float(base_targets.get("target_kcal", 2000.0))
    current_sodium = float(base_targets.get("micros_and_guidance", {}).get("max_sodium_mg", 2300.0))
    current_fiber = float(base_targets.get("micros_and_guidance", {}).get("fiber_g", 28.0))
    current_sugar = float(
        base_targets.get("micros_and_guidance", {}).get("max_added_sugar_g", 50.0)
    )
    current_protein = float(base_targets.get("macros", {}).get("protein_g", 70.0))

    # Candidate constraints list
    candidates: List[ClinicalConstraint] = []
    clinical_guidance: List[Dict[str, Any]] = []

    # 1. Process active clinical conditions
    for cond_input in active_conditions:
        key = normalize_condition_name(cond_input)
        if key in conditions_cfg:
            cond_data = conditions_cfg[key]
            cond_name = cond_data.get("name", key.title())
            citation = cond_data.get("citation", "Clinical guideline")

            # Collect guidance notes
            for g in cond_data.get("guidance", []):
                clinical_guidance.append(
                    {
                        "condition": cond_name,
                        "citation": citation,
                        "advice": g,
                    }
                )

            # Evaluate constraints
            constraints = cond_data.get("constraints", {})

            # Sodium max limit
            if "max_sodium_mg" in constraints:
                val = float(constraints["max_sodium_mg"]["value"])
                candidates.append(
                    ClinicalConstraint(
                        nutrient="max_sodium_mg",
                        bound_type="max",
                        value=val,
                        unit="mg/day",
                        condition_key=key,
                        condition_name=cond_name,
                        citation=citation,
                        reason=constraints["max_sodium_mg"]["reason"],
                    )
                )

            # Fiber min target
            if "min_fiber_per_1000kcal" in constraints:
                val = float(constraints["min_fiber_per_1000kcal"]["value"])
                total_fiber_target = round((target_kcal / 1000.0) * val, 1)
                candidates.append(
                    ClinicalConstraint(
                        nutrient="min_fiber_g",
                        bound_type="min",
                        value=total_fiber_target,
                        unit="g/day",
                        condition_key=key,
                        condition_name=cond_name,
                        citation=citation,
                        reason=constraints["min_fiber_per_1000kcal"]["reason"],
                    )
                )

            # Sugar max percentage
            if "max_sugar_pct_kcal" in constraints:
                pct = float(constraints["max_sugar_pct_kcal"]["value"])
                sugar_g = round((target_kcal * (pct / 100.0)) / 4.0, 1)
                candidates.append(
                    ClinicalConstraint(
                        nutrient="max_added_sugar_g",
                        bound_type="max",
                        value=sugar_g,
                        unit="g/day",
                        condition_key=key,
                        condition_name=cond_name,
                        citation=citation,
                        reason=constraints["max_sugar_pct_kcal"]["reason"],
                    )
                )

            # Saturated fat max percentage
            if "max_sat_fat_pct_kcal" in constraints:
                pct = float(constraints["max_sat_fat_pct_kcal"]["value"])
                sat_fat_g = round((target_kcal * (pct / 100.0)) / 9.0, 1)
                candidates.append(
                    ClinicalConstraint(
                        nutrient="max_sat_fat_g",
                        bound_type="max",
                        value=sat_fat_g,
                        unit="g/day",
                        condition_key=key,
                        condition_name=cond_name,
                        citation=citation,
                        reason=constraints["max_sat_fat_pct_kcal"]["reason"],
                    )
                )

            # Cholesterol max limit
            if "max_cholesterol_mg" in constraints:
                val = float(constraints["max_cholesterol_mg"]["value"])
                candidates.append(
                    ClinicalConstraint(
                        nutrient="max_cholesterol_mg",
                        bound_type="max",
                        value=val,
                        unit="mg/day",
                        condition_key=key,
                        condition_name=cond_name,
                        citation=citation,
                        reason=constraints["max_cholesterol_mg"]["reason"],
                    )
                )

            # Protein min ratio
            if "min_protein_g_per_kg" in constraints:
                val = float(constraints["min_protein_g_per_kg"]["value"])
                total_protein_g = round(weight_kg * val, 1)
                candidates.append(
                    ClinicalConstraint(
                        nutrient="min_protein_g",
                        bound_type="min",
                        value=total_protein_g,
                        unit="g/day",
                        condition_key=key,
                        condition_name=cond_name,
                        citation=citation,
                        reason=constraints["min_protein_g_per_kg"]["reason"],
                    )
                )

    # 2. Process dietary preferences / restrictions from vocabulary
    for restr in active_restrictions:
        restr_clean = str(restr).lower().strip().replace(" ", "_")
        if restr_clean == "low_sodium":
            candidates.append(
                ClinicalConstraint(
                    nutrient="max_sodium_mg",
                    bound_type="max",
                    value=1500.0,
                    unit="mg/day",
                    condition_key="low_sodium",
                    condition_name="Low Sodium Preference",
                    citation="FDA Low Sodium Standard / Diet Preferences",
                    reason="Restricts daily sodium intake to <= 1,500 mg.",
                )
            )
        elif restr_clean == "low_sugar":
            sugar_g = round((target_kcal * 0.05) / 4.0, 1)
            candidates.append(
                ClinicalConstraint(
                    nutrient="max_added_sugar_g",
                    bound_type="max",
                    value=sugar_g,
                    unit="g/day",
                    condition_key="low_sugar",
                    condition_name="Low Sugar Preference",
                    citation="Dietary Guidelines / Preference",
                    reason="Restricts free added sugar to <= 5% of energy.",
                )
            )

    # 3. Conflict Resolution Engine: Select strictest bound per nutrient
    audit_trail: Dict[str, Dict[str, Any]] = {}

    # Initialize with default baseline bounds
    final_sodium = current_sodium
    audit_trail["max_sodium_mg"] = {
        "final_value": final_sodium,
        "unit": "mg/day",
        "ruling_condition": "General Dietary Guidelines (DGA)",
        "citation": "USDA Dietary Guidelines for Americans (2020-2025)",
        "reason": "Standard healthy adult sodium cap of 2,300 mg/day.",
    }

    final_fiber = current_fiber
    audit_trail["fiber_g"] = {
        "final_value": final_fiber,
        "unit": "g/day",
        "ruling_condition": "General Dietary Guidelines (DGA)",
        "citation": "Institute of Medicine (IOM) Dietary Reference Intakes",
        "reason": "Baseline 14 g per 1,000 kcal recommendation.",
    }

    final_sugar = current_sugar
    audit_trail["max_added_sugar_g"] = {
        "final_value": final_sugar,
        "unit": "g/day",
        "ruling_condition": "General Dietary Guidelines (DGA)",
        "citation": "WHO Sugar Guideline / DGA",
        "reason": "Standard cap of < 10% of energy from added sugars.",
    }

    final_protein = current_protein
    audit_trail["protein_g"] = {
        "final_value": final_protein,
        "unit": "g/day",
        "ruling_condition": "Baseline Nutritional Calculation",
        "citation": "Institute of Medicine (IOM)",
        "reason": "Base protein requirement based on user goal.",
    }

    final_sat_fat = round((target_kcal * 0.10) / 9.0, 1)  # standard < 10% kcal
    audit_trail["max_sat_fat_g"] = {
        "final_value": final_sat_fat,
        "unit": "g/day",
        "ruling_condition": "General Dietary Guidelines (DGA)",
        "citation": "DGA 2020-2025",
        "reason": "Limit saturated fat to < 10% of total daily energy.",
    }

    final_cholesterol = 300.0  # standard baseline
    audit_trail["max_cholesterol_mg"] = {
        "final_value": final_cholesterol,
        "unit": "mg/day",
        "ruling_condition": "General Heart-Healthy Guidance",
        "citation": "AHA Dietary Guidelines",
        "reason": "General adult dietary cholesterol reference.",
    }

    # Evaluate candidate rules
    for c in candidates:
        if c.bound_type == "max":
            # Strictest is MINIMUM value
            if c.nutrient == "max_sodium_mg" and c.value < final_sodium:
                final_sodium = c.value
                audit_trail["max_sodium_mg"] = {
                    "final_value": final_sodium,
                    "unit": c.unit,
                    "ruling_condition": c.condition_name,
                    "citation": c.citation,
                    "reason": c.reason,
                }
            elif c.nutrient == "max_added_sugar_g" and c.value < final_sugar:
                final_sugar = c.value
                audit_trail["max_added_sugar_g"] = {
                    "final_value": final_sugar,
                    "unit": c.unit,
                    "ruling_condition": c.condition_name,
                    "citation": c.citation,
                    "reason": c.reason,
                }
            elif c.nutrient == "max_sat_fat_g" and c.value < final_sat_fat:
                final_sat_fat = c.value
                audit_trail["max_sat_fat_g"] = {
                    "final_value": final_sat_fat,
                    "unit": c.unit,
                    "ruling_condition": c.condition_name,
                    "citation": c.citation,
                    "reason": c.reason,
                }
            elif c.nutrient == "max_cholesterol_mg" and c.value < final_cholesterol:
                final_cholesterol = c.value
                audit_trail["max_cholesterol_mg"] = {
                    "final_value": final_cholesterol,
                    "unit": c.unit,
                    "ruling_condition": c.condition_name,
                    "citation": c.citation,
                    "reason": c.reason,
                }

        elif c.bound_type == "min":
            # Strictest is MAXIMUM value
            if c.nutrient == "min_fiber_g" and c.value > final_fiber:
                final_fiber = c.value
                audit_trail["fiber_g"] = {
                    "final_value": final_fiber,
                    "unit": c.unit,
                    "ruling_condition": c.condition_name,
                    "citation": c.citation,
                    "reason": c.reason,
                }
            elif c.nutrient == "min_protein_g" and c.value > final_protein:
                final_protein = c.value
                audit_trail["protein_g"] = {
                    "final_value": final_protein,
                    "unit": c.unit,
                    "ruling_condition": c.condition_name,
                    "citation": c.citation,
                    "reason": c.reason,
                }

    # Recalculate macros with adjusted protein if needed
    protein_kcal = final_protein * 4.0
    fat_g = float(base_targets.get("macros", {}).get("fat_g", round(target_kcal * 0.28 / 9.0, 1)))
    fat_kcal = fat_g * 9.0
    carbs_kcal = max(0.0, target_kcal - (protein_kcal + fat_kcal))
    carbs_g = round(carbs_kcal / 4.0, 1)

    adjusted_targets = {
        "target_kcal": target_kcal,
        "macros": {
            "protein_g": final_protein,
            "protein_kcal": round(protein_kcal),
            "fat_g": fat_g,
            "fat_kcal": round(fat_kcal),
            "carbs_g": carbs_g,
            "carbs_kcal": round(carbs_kcal),
        },
        "micros_and_guidance": {
            "fiber_g": final_fiber,
            "max_added_sugar_g": final_sugar,
            "max_sodium_mg": final_sodium,
            "max_sat_fat_g": final_sat_fat,
            "max_cholesterol_mg": final_cholesterol,
            "daily_water_ml": base_targets.get("micros_and_guidance", {}).get(
                "daily_water_ml", 2500
            ),
            "daily_water_liters": base_targets.get("micros_and_guidance", {}).get(
                "daily_water_liters", 2.5
            ),
        },
    }

    return {
        "adjusted_targets": adjusted_targets,
        "audit_trail": audit_trail,
        "clinical_guidance": clinical_guidance,
        "active_conditions": active_conditions,
        "active_restrictions": active_restrictions,
    }
